node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Look up the order
const order = db.prepare(\"SELECT * FROM orders WHERE order_id LIKE '%E0E671%'\").all();
console.log('Orders:', JSON.stringify(order, null, 2));

// Also search order_items for the item
const items = db.prepare(\"SELECT * FROM order_items WHERE item_id LIKE '%E5801A%'\").all();
console.log('Items:', JSON.stringify(items, null, 2));

// Check warranties
const warranties = db.prepare(\"SELECT * FROM warranties WHERE item_id LIKE '%E5801A%' OR order_id LIKE '%E0E671%'\").all();
console.log('Warranties:', JSON.stringify(warranties, null, 2));
"

